Idempotency-Key: 6b1f9e2a-...
```

Reject with 400 if it's missing (order creation is exactly the kind of endpoint where you want this mandatory, not best-effort).

**2. Add a claim table with a unique constraint**

```sql
CREATE TABLE idempotency_keys (
  account_id  int NOT NULL,
  key         text NOT NULL,
  request_hash text NOT NULL,
  status_code int,
  response_body jsonb,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (account_id, key)
);
```

The primary key is what makes concurrent duplicate requests safe — two racing inserts with the same key can't both "win."

**3. Add a multi-statement transaction helper**

`db.write` commits one statement; idempotency needs claim-insert + order-insert + response-store in one transaction. Add something like `db.transaction(fn)` that hands `fn` a connected client and does `BEGIN`/`COMMIT`/`ROLLBACK` around it, and use that instead of `db.write` in this handler.

**4. Handler logic**

```js
router.post("/", async (req, res) => {
  const key = req.header("Idempotency-Key");
  if (!key) return res.status(400).json({ error: "Idempotency-Key required" });

  const requestHash = hash({ sku: req.body.sku, quantity: req.body.quantity });

  const result = await db.transaction(async (client) => {
    const claim = await client.query(
      `INSERT INTO idempotency_keys (account_id, key, request_hash)
       VALUES ($1, $2, $3)
       ON CONFLICT (account_id, key) DO NOTHING
       RETURNING *`,
      [req.user.accountId, key, requestHash]
    );

    if (claim.rows.length === 0) {
      // key already seen — fetch what happened last time
      const existing = await client.query(
        `SELECT * FROM idempotency_keys WHERE account_id = $1 AND key = $2`,
        [req.user.accountId, key]
      );
      const prior = existing.rows[0];
      if (prior.request_hash !== requestHash) {
        return { conflict: true }; // same key, different payload
      }
      if (prior.response_body === null) {
        return { inFlight: true }; // original request still processing
      }
      return { cached: prior };
    }

    const order = await client.query(
      "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
      [req.user.accountId, req.body.sku, req.body.quantity]
    );

    await client.query(
      `UPDATE idempotency_keys SET status_code = 201, response_body = $1
       WHERE account_id = $2 AND key = $3`,
      [order.rows[0], req.user.accountId, key]
    );

    return { fresh: order.rows[0] };
  });

  if (result.conflict) return res.status(422).json({ error: "Idempotency-Key reused with different request body" });
  if (result.inFlight) return res.status(409).json({ error: "request with this key is already being processed" });
  if (result.cached) return res.status(result.cached.status_code).json(result.cached.response_body);
  return res.status(201).json(result.fresh);
});
```

